PREFIX brick: <http://brickschema.org/schema/1.2/Brick#>
PREFIX ref: <http://brickschema.org/schema/1.2/brick#ref:>
SELECT ?zone ?elec ?occ ?elecTS ?occTS
WHERE {
  ?zone brick:hasSubclass* brick:Zone .
  FILTER(str(?zone) ENDSWITH "Perimeter_top_ZN_4")
  OPTIONAL { ?s brick:isAOf ?zone . ?s brick:hasPropertyType* brick:ElectricPower . ?s ref:hasTimeseriesId ?elecTS . }
  OPTIONAL { ?o brick:isAOf ?zone . ?o brick:hasPropertyType* brick:Occupancy . ?o ref:hasTimeseriesId ?occTS . }
}

PREFIX brick: <http://brickschema.org/schema/1.2/Brick#>
SELECT ?zone WHERE {
  ?zone a brick:Zone .
} LIMIT 50

